const data = String($('Telegram Event Trigger').first().json.callback_query?.data || '').trim();

const match = /^(approve|reject|edit)_(\d+)$/.exec(data);

if (!match) {
  throw new Error("Invalid callback data");
}

return [{
  json: {
    action: match[1],
    mail_id: Number(match[2])
  }
}];

const rows = $input.all().map(item => item.json);

const now = Date.now();
const last24h = now - 24 * 60 * 60 * 1000;
const limit = 5;

const sentCount24h = rows.filter(row => {
  if (row.status !== 'sent') return false;
  if (!row.sent_at) return false;

  const timestamp = new Date(row.sent_at).getTime();

  return Number.isFinite(timestamp) &&
    timestamp >= last24h &&
    timestamp <= now;
}).length;

return [{
  json: {
    sender: rows[0]?.sender,
    sentCount24h,
    limit,
    allowed: sentCount24h < limit
  }
}];
